function stemQuery(text) {
  return [...new Set(tokenize(text).map((t) => stem(t.raw)))];
}

/**
 * Create a search index.
 *
 * @param {object} opts
 * @param {string[]} opts.fields  Document fields to index (default ["body"]).
 * @param {object}   opts.boost   Per-field weight multipliers, e.g. { title: 5 }.
 *                                Fields not listed default to boost 1.
 *
 * Documents must have an `id` property plus values for each indexed field.
 * Re-adding an existing id replaces the old document cleanly (postings updated).
 */
export function createIndex({ fields = ["body"], boost = {} } = {}) {
  const boosts = Object.fromEntries(fields.map((f) => [f, boost[f] ?? 1]));

  /** id -> { doc, fields: { [field]: { text, terms: [{term,start,end}], tf: Map } } } */
  const docs = new Map();
  /** term -> Set<docId>  (the postings list; df(term) = set.size) */
  const postings = new Map();

  function indexField(field, text) {
    const tokens = tokenize(text);
    const terms = tokens.map((t) => ({ term: stem(t.raw), start: t.start, end: t.end }));
    const tf = new Map();
    for (const { term } of terms) tf.set(term, (tf.get(term) ?? 0) + 1);
    return { text: String(text ?? ""), terms, tf };
  }

  function add(doc) {
    if (!doc || doc.id === undefined || doc.id === null) {
      throw new Error("add(): document must have an `id`");
    }
    if (docs.has(doc.id)) remove(doc.id); // replace cleanly

    const entry = { doc, fields: {} };
    const touched = new Set();
    for (const field of fields) {
      const f = indexField(field, doc[field] ?? "");
      entry.fields[field] = f;
      for (const term of f.tf.keys()) touched.add(term);
    }
    docs.set(doc.id, entry);
    for (const term of touched) {
      let set = postings.get(term);
      if (!set) postings.set(term, (set = new Set()));
      set.add(doc.id);
    }
    return doc.id;
  }

  /**
   * Remove a document and scrub every posting entry referencing it, so it can
   * never surface in later queries or snippets. Returns true if it existed.
   */
  function remove(id) {
    const entry = docs.get(id);
    if (!entry) return false;
    for (const field of fields) {
      for (const term of entry.fields[field].tf.keys()) {
        const set = postings.get(term);
        if (!set) continue;
        set.delete(id);
        if (set.size === 0) postings.delete(term); // no dangling empty lists
      }
    }
    docs.delete(id);
    return true;
  }

  /** Boosted term frequency: sum over fields of tf_in_field * fieldBoost. */
  function boostedTf(entry, term) {
    let tf = 0;
    for (const field of fields) {
      tf += (entry.fields[field].tf.get(term) ?? 0) * boosts[field];
    }
    return tf;
  }

  /**
   * Query the index. Returns [{ id, score, doc }] sorted by descending score.
   * idf(term) = ln(N / df), so a term appearing in every document contributes
   * exactly zero to every score — ranking is driven purely by rarer terms.
   * Docs matching only such ubiquitous terms still appear (score 0).
   */
  function query(text) {
    const N = docs.size;
    if (N === 0) return [];
    const stems = stemQuery(text);
    const scores = new Map();

    for (const term of stems) {
      const set = postings.get(term);
      if (!set || set.size === 0) continue;
      const idf = Math.max(Math.log(N / set.size), 0);
      for (const id of set) {
        const entry = docs.get(id);
        scores.set(id, (scores.get(id) ?? 0) + boostedTf(entry, term) * idf);
      }
    }

    return [...scores.entries()]
      .map(([id, score]) => ({ id, score, doc: docs.get(id).doc }))
      .sort((a, b) => b.score - a.score || String(a.id).localeCompare(String(b.id)));
  }

  /**
   * Best-matching snippet for a document.
   *
   * Finds occurrences of the query's stemmed terms in the doc's original field
   * text, picks the smallest window of consecutive matches covering the most
   * distinct query terms (earliest wins ties), then expands it by `radius`
   * characters on each side (clamped to the text bounds).
   *
   * Returns { field, text, start, end, matches } where start/end are absolute
   * character offsets into the ORIGINAL field text (text === orig.slice(start,end))
   * and matches is [{term,start,end}] with absolute offsets. Returns null when
   * the doc is unknown or nothing matches.
   */
  function snippet(id, queryText, radius = 30) {
    const entry = docs.get(id);
    if (!entry) return null;
    const stems = new Set(stemQuery(queryText));
    if (stems.size === 0) return null;

    // Prefer the highest-boosted field that has any hit.
    const ordered = [...fields].sort((a, b) => boosts[b] - boosts[a]);
    for (const field of ordered) {
      const text = entry.fields[field].text;
      const hits = entry.fields[field].terms.filter((t) => stems.has(t.term));
      if (hits.length === 0) continue;

      // Brute-force the best [l..r] window: max distinct terms covered,
      // then minimal character span, then earliest position.
      let best = null;
      for (let l = 0; l < hits.length; l++) {
        const seen = new Set();
        for (let r = l; r < hits.length; r++) {
          seen.add(hits[r].term);
          const span = hits[r].end - hits[l].start;
          const cand = { l, r, distinct: seen.size, span };
          if (
            best === null ||
            cand.distinct > best.distinct ||
            (cand.distinct === best.distinct && cand.span < best.span)
          ) {
            best = cand;
          }
        }
      }

      const first = hits[best.l];
      const lastHit = hits[best.r];
      const start = Math.max(0, first.start - radius);
      const end = Math.min(text.length, lastHit.end + radius);

      return {
        field,
        text: text.slice(start, end),
        start,
        end,
        matches: hits.slice(best.l, best.r + 1).map((m) => ({ ...m })),
      };
    }
    return null;
  }

  return { add, remove, query, snippet, tokenize, stem };
}
